program = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                markers.append((r, c))

    marker_set = set(markers)
    for r, c in markers:
        row_twos = sum(value == 2 for value in grid[r])
        col_twos = sum(grid[rr][c] == 2 for rr in range(h))
        if row_twos > col_twos:
            ray = [(rr, c) for rr in range(h)]
        else:
            ray = [(r, cc) for cc in range(w)]

        crossings = []
        for rr, cc in ray:
            if grid[rr][cc] == 2 and (rr, cc) not in marker_set:
                crossings.append((rr, cc))
            if out[rr][cc] == 0:
                out[rr][cc] = 1

        for cr, cc in crossings:
            for rr in range(max(0, cr - 1), min(h, cr + 2)):
                for col in range(max(0, cc - 1), min(w, cc + 2)):
                    if (rr, col) != (cr, cc) and grid[rr][col] != 3:
                        out[rr][col] = 1
    return out
'''
